package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/** A person kept on a sheet, with a name and a grade (A, B or C) that is dated: each grade is in force from its
 * from-date until the next, the first one given from the beginning of time. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** The date the person is retired from; null while not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Whether the person is on hold: while held, their OPEN and PENDING claims count in no live total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {}

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(grade, null));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The person's grades by from-date, the first one given (with no from-date) first. */
    public List<GradeFrom> getGrades() {
        return grades.stream().sorted(GradeFrom.BY_FROM).toList();
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> g.getFrom() == null || !g.getFrom().isAfter(date))
                .max(GradeFrom.BY_FROM)
                .map(GradeFrom::getGrade)
                .orElseThrow();
    }

    /** Record the grade from a from-date, replacing any the person had from that date and keeping the others. */
    public void setGrade(String grade, LocalDate from) {
        grades.removeIf(g -> Objects.equals(g.getFrom(), from));
        grades.add(new GradeFrom(grade, from));
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether a claim dated {@code date} is after the person's retirement. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PersonService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final SheetRepository sheets;
    private final SheetService sheetService;
    private final RollupService rollup;
    private final Audit audit;

    public PersonService(PersonRepository people, PatronRepository patrons, SheetRepository sheets, SheetService sheetService,
            RollupService rollup, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.sheets = sheets;
        this.sheetService = sheetService;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's people in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        requireSheet(sheetId);
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String user, String sheetId, String name, String grade) {
        requireSheet(sheetId);
        String trimmed = name.trim();
        requireNameFree(sheetId, trimmed, null);
        Snapshot before = rollup.snapshot(sheetId);
        Person person = people.saveAndFlush(new Person(sheetId, trimmed, grade));
        audit.recordOnCommit(entry("PERSON_ADDED", user, person, sheetService.today(sheetId)));
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /**
     * Saves changes to a person. When {@code version} is given it is the version the editor loaded,
     * and the save is refused if the person has been saved since. The grade is recorded from {@code gradeFrom},
     * the sheet's today when none is given, keeping the grades the person has from other dates.
     */
    @Transactional
    public Person update(String user, String sheetId, Long id, String name, String grade, LocalDate gradeFrom,
            Long version) {
        LocalDate today = sheetService.today(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (version != null && version != person.getVersion()) {
            throw changedMeanwhile();
        }
        String trimmed = name.trim();
        requireNameFree(sheetId, trimmed, id);
        Snapshot before = rollup.snapshot(sheetId);
        person.setName(trimmed);
        person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
        try {
            people.flush();
        } catch (ObjectOptimisticLockingFailureException e) {
            throw changedMeanwhile();
        }
        audit.recordOnCommit(entry("PERSON_EDITED", user, person, today));
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /** Retire the person from a date, the sheet's today when none is given; claims dated after it are refused. */
    @Transactional
    public Person retire(String user, String sheetId, Long id, LocalDate from) {
        LocalDate date = from != null ? from : sheetService.today(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        person.setRetiredFrom(date);
        people.flush();
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " from=" + date);
        return person;
    }

    /** Put the person on hold, or take them off it when held; while held their OPEN and PENDING claims count in no live
     * total. */
    @Transactional
    public Person toggleHold(String user, String sheetId, Long id) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Snapshot before = rollup.snapshot(sheetId);
        person.setHeld(!person.isHeld());
        people.flush();
        audit.recordOnCommit((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + sheetId
                + " by=" + user + " name=" + person.getName());
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /** Each person's patrons' ids, by person id, in the order they were named. */
    @Transactional(readOnly = true)
    public Map<Long, List<Long>> patronIds(String sheetId) {
        Map<Long, List<Long>> by = new LinkedHashMap<>();
        for (Patron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
            by.computeIfAbsent(patron.getPersonId(), k -> new ArrayList<>()).add(patron.getPatronId());
        }
        return by;
    }

    /** Name another person on the sheet as the person's patron; refused for the person themselves and for one
     * already named. */
    @Transactional
    public Person addPatron(String user, String sheetId, Long id, Long patronId) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
        if (patron.getId().equals(person.getId())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be their own patron.");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That patron is already named.");
        }
        patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " patron=" + patron.getName());
        return person;
    }

    /** A line naming the person and the grade they have in force on the sheet's today. */
    private static String entry(String event, String user, Person person, LocalDate today) {
        return event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(today);
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved that person since it was opened.");
    }

    private void requireNameFree(String sheetId, String name, Long exceptId) {
        if (people.nameInUse(sheetId, name, exceptId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
        }
    }

    private void requireSheet(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet.");
        }
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementService.Summary;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The people kept on a sheet. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            Long version) {}

    /** A grade the person has from a from-date (none: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {}

    /** A person shows how many statements were taken for them and the last one's due-total (n/a when it was)
     * and date; none of those before the first; and the ids of their patrons, in the order they were named. Its
     * grade is the one in force on the sheet's today, and its grades every one recorded, by from-date. */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version, int statementCount,
            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held,
            List<Long> patronIds) {

        public static PersonView of(Person person, LocalDate today, Map<Long, Summary> statements,
                Map<Long, List<Long>> patrons) {
            Summary summary = statements.get(person.getId());
            Statement last = summary != null ? summary.last() : null;
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFrom())).toList(),
                    person.getVersion(),
                    summary != null ? summary.count() : 0,
                    last == null ? null : last.getDueTotal() != null ? last.getDueTotal().toPlainString() : "n/a",
                    last != null ? last.getTakenOn() : null, person.getRetiredFrom(), person.isHeld(),
                    patrons.getOrDefault(person.getId(), List.of()));
        }
    }

    private final PersonService service;
    private final StatementService statements;
    private final SheetService sheets;

    public PersonController(PersonService service, StatementService statements, SheetService sheets) {
        this.service = service;
        this.statements = statements;
        this.sheets = sheets;
    }

    @GetMapping
    public List<PersonView> list(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        List<Person> people = service.list(sheetId);
        Map<Long, Summary> taken = statements.summaries(sheetId);
        Map<Long, List<Long>> patrons = service.patronIds(sheetId);
        LocalDate today = sheets.today(sheetId);
        return people.stream().map(p -> PersonView.of(p, today, taken, patrons)).toList();
    }

    @PostMapping
    public PersonView add(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody PersonForm form) {
        return view(sheetId, service.add(user, sheetId, form.name(), form.grade()));
    }

    @PutMapping("/{id}")
    public PersonView update(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody PersonForm form) {
        return view(sheetId, service.update(user, sheetId, id, form.name(), form.grade(), form.gradeFrom(),
                form.version()));
    }

    public record RetireForm(LocalDate from) {}

    /** Retire the person from a date, the sheet's today when none is given. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @RequestBody RetireForm form) {
        return view(sheetId, service.retire(user, sheetId, id, form.from()));
    }

    /** Put the person on hold, or take them off it when held. */
    @PostMapping("/{id}/hold")
    public PersonView hold(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id) {
        return view(sheetId, service.toggleHold(user, sheetId, id));
    }

    public record PatronForm(@NotNull Long patronId) {}

    /** Name another person on the sheet as the person's patron. */
    @PostMapping("/{id}/patrons")
    public PersonView addPatron(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody PatronForm form) {
        return view(sheetId, service.addPatron(user, sheetId, id, form.patronId()));
    }

    /** Take a statement for the person. */
    @PostMapping("/{id}/statement")
    public PersonView statement(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id) {
        return view(sheetId, statements.take(user, sheetId, id));
    }

    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, sheets.today(sheetId), statements.summaries(sheetId), service.patronIds(sheetId));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
 * claimed-total and due-total. A change takes them before it alters anything and hands them back after, and
 * every figure it moved is written to the audit after the change's own lines. Called within the change's
 * transaction.
 */
@Service
public class RollupService {

    /** Shown in place of a due-total whose grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** A person's figures, as the screen shows them. */
    public record Figures(String name, String claimed, String dueTotal) {}

    /** The sheet's figures at one moment: each person's by id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}

    /** What a claim's late charge goes by: the sheet's today (none when there is no such sheet) and its late
     * percent; and the date its rounding goes by, the policy date or else the sheet's today. */
    private record Lateness(LocalDate today, BigDecimal latePct, LocalDate policyDate) {

        static Lateness of(Sheet sheet) {
            return sheet == null ? new Lateness(null, BigDecimal.ZERO, null)
                    : new Lateness(sheet.getToday(), sheet.getLatePct(), sheet.roundingDate());
        }

        /** How a claim's live figures round, by the date they go by: one before the policy date rounds half up,
         * one on or after it half to even. */
        RoundingMode rounding(LocalDate roundsBy) {
            return policyDate != null && roundsBy.isBefore(policyDate) ? RoundingMode.HALF_UP
                    : RoundingMode.HALF_EVEN;
        }
    }

    /** The days in each period an overdue claim gains its late percent for. */
    private static final int LATE_PERIOD_DAYS = 30;

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
    public Snapshot snapshot(String sheetId) {
        Lateness late = latenessOf(sheetId);
        LocalDate today = late.today();
        BigDecimal floor = floorOf(sheetId);
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        for (Claim claim : all) {
            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
        }
        Map<String, LocalDate> datesByNumber = datesByNumber(all);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
                    .filter(c -> counts(c, person)).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean frozen = false;
            for (Claim claim : counted) {
                claimed = claimed.add(claim.getAmount().setScale(2));
                frozen |= keepsFigure(claim);
                BigDecimal figure = dueOf(claim, ratesOn(person, claim.getDate(), byGrade), floor, late,
                        roundsBy(claim, datesByNumber));
                if (figure != null) {
                    due = due.add(figure.setScale(2));
                }
            }
            // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
            boolean rated = rated(person, counted, today, byGrade);
            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
            claimedTotal = claimedTotal.add(claimed);
            if (rated || frozen) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), personDue));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** The due-total of the sheet's claims that count (a held person's OPEN and PENDING ones do not) dated from and to, inclusive: the sum of their dues,
     * late charges included, n/a ones skipped. */
    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
        BigDecimal floor = floorOf(sheetId);
        Lateness late = latenessOf(sheetId);
        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            byId.put(person.getId(), person);
        }
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<String, LocalDate> datesByNumber = datesByNumber(all);
        for (Claim claim : all) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !counts(claim, person)
                    || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                continue;
            }
                .map(due -> claim.isCorrection() ? due : due.max(floor.setScale(2)))
                .orElse(null);
    }

    private Lateness latenessOf(String sheetId) {
        return Lateness.of(sheets.findById(sheetId).orElse(null));
    }

    /** The sheet's floor; 1.00, the one a sheet starts with, when there is no such sheet. */
    private BigDecimal floorOf(String sheetId) {
        return sheets.findById(sheetId).map(s -> s.getFloor()).orElse(new BigDecimal("1.00"));
    }

    /** Whether a claim keeps a figure whatever the rates: settled at one, or bound to one (not n/a) by a
     * statement while not PENDING. */
    public static boolean keepsFigure(Claim claim) {
        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
    }

    /** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound,
     * but shows its live figure, and is bound again if it is rejected. */
    private static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due; a held person's OPEN and
     * PENDING ones do not. */
    private static boolean counts(Claim claim, Person person) {
        return (claim.getStatus().isOpen() && !person.isHeld())
                || claim.getStatus() == ClaimStatus.SETTLED;
    }
}

