content.content:
export type ClaimAction = 'open' | 'settle' | 'approve' | 'void';

/** Whether a claim is still open: OPEN, or PENDING a steward. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound, but
 * shows its live figure. */
function bound(claim: Claim): boolean {
  return claim.stated && claim.status !== 'PENDING';
}

-- A person can be put on hold; while held their OPEN claims count in no live total.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- Each sheet keeps its own "today": every date-dependent decision and default date uses it, never
-- the real clock. It starts as the real date when the sheet is first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- People kept on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);

